    const lines = [], capture = (m) => lines.push(m);
    const wl = (() => { const out = []; L.command(["--aircraft", "jet", "--train", "wide", "--smoke", "--runs", "1", "--iters", "0", "--quiet"], { out: (m) => out.push(m), err: (m) => out.push(m), finish: () => ({ shipped: {}, runs: [], champion: null, verdict: { ok: false, reasons: [] } }), run: () => ({ shipped: {}, runs: [], champion: null, verdict: { ok: false, reasons: [] } }) }); return out; })();
    const header = (argv) => { const out = []; L.command(argv, { out: (m) => out.push(m), err: (m) => out.push(m), run: () => ({ shipped: {}, runs: [], champion: null, verdict: { ok: false, reasons: [] } }) }); return out[0] || ""; };
    ok("!! THE COMMAND SAYS WHICH RECIPE IT IS RUNNING: the first line of a wide run names the WIDE training, the number of batches, the duels in each and the prune set; a fixed run's does not mention it",
        /\(WIDE training: each iteration judged on one of 2 batches of 2 fresh duels, pruned on 4 more\)/.test(header(["--aircraft", "jet", "--train", "wide", "--smoke", "--runs", "1", "--iters", "3"])) && !/WIDE/.test(header(["--aircraft", "jet", "--smoke", "--runs", "1", "--iters", "3"])) && Array.isArray(wl));
    const dumpW = L.dumpOf({ shipped: { heldOut: { score: 0, by: Object.fromEntries(L.MEMBERS.map((m) => [m, { mean: 0, lost: [] }])) }, pool: { score: 0, by: Object.fromEntries(L.MEMBERS.map((m) => [m, { mean: 0, lost: [] }])) } }, runs: [], champion: null, verdict: { ok: false, reasons: [] } }, wO), dumpF = L.dumpOf({ shipped: { heldOut: { score: 0, by: Object.fromEntries(L.MEMBERS.map((m) => [m, { mean: 0, lost: [] }])) }, pool: { score: 0, by: Object.fromEntries(L.MEMBERS.map((m) => [m, { mean: 0, lost: [] }])) } }, runs: [], champion: null, verdict: { ok: false, reasons: [] } }, fO);
    ok("the dump records the recipe's training mode (wide / fixed), so a dump says how its runs were made", dumpW.recipe.train === "wide" && dumpF.recipe.train === "fixed" && dumpW.recipe.aircraft === "jet");
    const jcc = { brain: L.BRAINS_JET.fly, hashes: { start: "aaaa1111", other: "bbbb2222" } }, sc2 = (v) => ({ score: v, by: Object.fromEntries(L.MEMBERS.map((m) => [m, { mean: v, lost: [], perScenario: [v], summary: sum() }])) });
    const champ = { seed: 12200, weights: Float32Array.from({ length: 1099 }, (_, i) => (i === 3 ? 0.5 : 0)), kept: 3, moved: 7, heldOut: sc2(0.55), pool: sc2(0.3), audit: { ...sc2(0.5), by: { ...sc2(0.5).by, self: { ...sc2(0.5).by.self, summary: { ...sum(), winsX: 60, draws: 20, winsY: 20, edge: 0.1, se: 0.02, z: 5 } } } }, classic: { audit: ev(120, 0.5), reserve: ev(120, 0.2), safety: clean }, vsAudit: { autopilot: { diff: 0.01, se: 0.01 }, other: { diff: 0.02, se: 0.01 } } };
    const res = { champion: champ, shipped: { heldOut: sc2(0.3), pool: sc2(0.3), audit: sc2(0.4), classic: { audit: ev(120, 0.45), reserve: ev(120, 0.19), safety: clean } }, verdict: { ok: true, reasons: [] } };
    const bw = L.blobOf(res, wO, jcc).by, bf = L.blobOf(res, fO, jcc).by;
