    ok("!! --train wide REACHES THE WORKERS: the dump of a two-process wide run is the dump of the one-process wide run to the bit (weights, seeds 12000 and 12001, scores), says train \"wide\", and the cache directory of the two-process run holds league-fly-smoke-wide-0.json and -1.json (the children were told the recipe, or their searches would have been fixed ones under a wide key)",
        ra.status === 0 && rb.status === 0 && e1 && e2 && JSON.stringify(e1) === JSON.stringify(e2) && e1.recipe.train === "wide" && e1.runs.map((r) => r.seed).join() === "12000,12001" && rc.status === 0 && cached.join() === "league-fly-smoke-wide-0.json,league-fly-smoke-wide-1.json", (ra.stderr + rb.stderr + rc.stderr).slice(0, 200) + cached.join());
